package com.ml.tblandroidtxt;

import static org.junit.Assert.*;

import androidx.test.core.app.ApplicationProvider;

import org.junit.Test;

import java.util.Arrays;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.util.concurrent.atomic.AtomicInteger;

/** Uses unique data and always cleans it up so it does not alter user projects. */
public class EditorialRepositoryInstrumentedTest {
    @Test public void persistsProjectChapterAssetsRunSceneGateAndEvidence() {
        EditorialRepository repo = new EditorialRepository(ApplicationProvider.getApplicationContext());
        long projectId = -1;
        try {
            EditorialRepository.Project project = new EditorialRepository.Project();
            project.seriesName = "QA Editorial " + System.nanoTime(); project.volumeName = "V1"; project.workflowHash = HashUtil.sha256("v5");
            projectId = repo.createProject(project);
            EditorialRepository.AssetSnapshot raw = new EditorialRepository.AssetSnapshot(EditorialWorkflowV5.AssetRole.RAW, "content://qa/raw", "raw.txt", "原文\n◇◇◇\n終わり");
            EditorialRepository.AssetSnapshot draft = new EditorialRepository.AssetSnapshot(EditorialWorkflowV5.AssetRole.DRAFT, "content://qa/draft", "draft.txt", "Bản nháp");
            EditorialRepository.AssetSnapshot glossary = new EditorialRepository.AssetSnapshot(EditorialWorkflowV5.AssetRole.GLOSSARY, "content://qa/glossary", "glossary.txt", "A,B");
            EditorialRepository.AssetSnapshot pronoun = new EditorialRepository.AssetSnapshot(EditorialWorkflowV5.AssetRole.PRONOUN, "content://qa/pronoun", "pronoun.txt", "A,B,anh/em");
            long chapterId = repo.createChapter(projectId, "C01", "QA chapter", Arrays.asList(raw, draft, glossary, pronoun));
            assertEquals(EditorialWorkflowV5.ChapterState.L1_READY, repo.getChapter(chapterId).state);
            assertTrue(repo.assetsMatchSnapshot(chapterId, Arrays.asList(raw, draft, glossary, pronoun)));
            long runId = repo.createRun(chapterId, "L1", "fake", "fake/model", HashUtil.sha256("prompt"), project.workflowHash, "{\"assets\":4}");
            repo.saveScene(runId, "s1", "p000001", "p000003", "CLOSED", "{\"scene\":1}");
            repo.saveGate(runId, EditorialWorkflowV5.Gate.COVERAGE, EditorialWorkflowV5.GateStatus.CLOSED, "{\"ok\":true}");
            repo.saveEvidence(runId, "REPORT_L1", "{\"report\":true}");
            assertEquals(1, repo.evidenceCount(runId));
        } finally {
            if (projectId > 0) repo.deleteProject(projectId);
            repo.close();
        }
    }

    @Test public void segmentedL1CheckpointsEveryStructurallyMappedScene() throws Exception {
        EditorialRepository repo=new EditorialRepository(ApplicationProvider.getApplicationContext());long projectId=-1;
        try {EditorialRepository.Project project=new EditorialRepository.Project();project.seriesName="QA Segmented "+System.nanoTime();project.volumeName="V1";project.workflowHash=HashUtil.sha256("v5");projectId=repo.createProject(project);StringBuilder raw=new StringBuilder(),draft=new StringBuilder();for(int i=0;i<30;i++){raw.append(repeat('原',500));draft.append(repeat('v',500));if(i<29){raw.append("\n◇◇◇\n");draft.append("\n◇◇◇\n");}}
            long chapterId=repo.createChapter(projectId,"LONG","Long chapter",Arrays.asList(new EditorialRepository.AssetSnapshot(EditorialWorkflowV5.AssetRole.RAW,"memory://raw","raw.txt",raw.toString()),new EditorialRepository.AssetSnapshot(EditorialWorkflowV5.AssetRole.DRAFT,"memory://draft","draft.txt",draft.toString()),new EditorialRepository.AssetSnapshot(EditorialWorkflowV5.AssetRole.GLOSSARY,"memory://g","g.txt","term"),new EditorialRepository.AssetSnapshot(EditorialWorkflowV5.AssetRole.PRONOUN,"memory://p","p.txt","voice")));
            EditorialL1Runner runner=new EditorialL1Runner(repo,(settings,prompt,requestId)->{Matcher scene=Pattern.compile("SCENE: (scene-\\d+)").matcher(prompt.user),anchors=Pattern.compile("EXPECTED RAW ANCHORS: (p\\d+) -> (p\\d+)").matcher(prompt.user);assertTrue(scene.find());assertTrue(anchors.find());OpenAICompatibleClient.ChatResult response=new OpenAICompatibleClient.ChatResult();response.content="{\"sceneId\":\""+scene.group(1)+"\",\"rawStart\":\""+anchors.group(1)+"\",\"rawEnd\":\""+anchors.group(2)+"\",\"coverage\":\"ALIGNED\",\"status\":\"CLOSED\",\"issues\":[]}";response.totalTokens=10;return response;});EditorialL1Runner.Result result=runner.run(chapterId,new AppSettings());assertTrue(result.report.startsWith("REPORT_L1"));assertEquals(EditorialWorkflowV5.ChapterState.L1_CLOSED,repo.getChapter(chapterId).state);assertTrue(repo.evidenceCount(result.runId)>=34);
        }finally{if(projectId>0)repo.deleteProject(projectId);repo.close();}
    }
    @Test public void retryReusesClosedSceneAndCallsOnlyFailedScene() throws Exception {
        EditorialRepository repo=new EditorialRepository(ApplicationProvider.getApplicationContext());long projectId=-1;try{EditorialRepository.Project project=new EditorialRepository.Project();project.seriesName="QA Retry "+System.nanoTime();project.volumeName="V1";project.workflowHash=HashUtil.sha256("v5");projectId=repo.createProject(project);String raw=repeat('原',7000)+"\n◇◇◇\n"+repeat('終',7000),draft=repeat('a',7000)+"\n◇◇◇\n"+repeat('b',7000);long chapterId=repo.createChapter(projectId,"RETRY","Retry chapter",Arrays.asList(new EditorialRepository.AssetSnapshot(EditorialWorkflowV5.AssetRole.RAW,"memory://raw","raw.txt",raw),new EditorialRepository.AssetSnapshot(EditorialWorkflowV5.AssetRole.DRAFT,"memory://draft","draft.txt",draft),new EditorialRepository.AssetSnapshot(EditorialWorkflowV5.AssetRole.GLOSSARY,"memory://g","g.txt","term"),new EditorialRepository.AssetSnapshot(EditorialWorkflowV5.AssetRole.PRONOUN,"memory://p","p.txt","voice")));AtomicInteger calls=new AtomicInteger();EditorialL1Runner runner=new EditorialL1Runner(repo,(settings,prompt,requestId)->{int call=calls.incrementAndGet();Matcher scene=Pattern.compile("SCENE: (scene-\\d+)").matcher(prompt.user),anchors=Pattern.compile("EXPECTED RAW ANCHORS: (p\\d+) -> (p\\d+)").matcher(prompt.user);assertTrue(scene.find());assertTrue(anchors.find());OpenAICompatibleClient.ChatResult response=new OpenAICompatibleClient.ChatResult();if("scene-002".equals(scene.group(1))&&call==2){response.content="invalid";return response;}response.content="{\"sceneId\":\""+scene.group(1)+"\",\"rawStart\":\""+anchors.group(1)+"\",\"rawEnd\":\""+anchors.group(2)+"\",\"coverage\":\"ALIGNED\",\"status\":\"CLOSED\",\"issues\":[]}";return response;});try{runner.run(chapterId,new AppSettings());fail();}catch(Exception expected){assertEquals(EditorialWorkflowV5.ChapterState.FAILED,repo.getChapter(chapterId).state);}runner.retryFailedScene(chapterId,new AppSettings());assertEquals(3,calls.get());assertEquals(EditorialWorkflowV5.ChapterState.L1_CLOSED,repo.getChapter(chapterId).state);
        }finally{if(projectId>0)repo.deleteProject(projectId);repo.close();}
    }
    @Test public void l2ClosesRawLedgerBeforeOpeningDraftAndReport() throws Exception {
        EditorialRepository repo=new EditorialRepository(ApplicationProvider.getApplicationContext());long projectId=-1;
        try{EditorialRepository.Project project=new EditorialRepository.Project();project.seriesName="QA L2 "+System.nanoTime();project.volumeName="V1";project.workflowHash=HashUtil.sha256("v5");projectId=repo.createProject(project);long chapterId=repo.createChapter(projectId,"L2","L2",Arrays.asList(new EditorialRepository.AssetSnapshot(EditorialWorkflowV5.AssetRole.RAW,"m://r","r.txt","RAW_SECRET"),new EditorialRepository.AssetSnapshot(EditorialWorkflowV5.AssetRole.DRAFT,"m://d","d.txt","DRAFT_SECRET"),new EditorialRepository.AssetSnapshot(EditorialWorkflowV5.AssetRole.GLOSSARY,"m://g","g.txt","G"),new EditorialRepository.AssetSnapshot(EditorialWorkflowV5.AssetRole.PRONOUN,"m://p","p.txt","P")));long l1=repo.createRun(chapterId,"L1","fake","fake",HashUtil.sha256("p"),project.workflowHash,"{}");String report="{\"schema\":\"editorial-v5-evidence-1\",\"run\":\"L1\",\"chapterId\":\""+chapterId+"\",\"scenes\":[{\"id\":\"s1\",\"rawStart\":\"p1\",\"rawEnd\":\"p1\",\"coverage\":\"ALIGNED\",\"status\":\"CLOSED\"}],\"issues\":[],\"gates\":{\"coverage\":\"CLOSED\",\"fidelity\":\"CLOSED\",\"referenceVoice\":\"CLOSED\",\"continuityStructure\":\"CLOSED\"}}";repo.saveEvidence(l1,"REPORT_L1_JSON",report);repo.transitionChapter(chapterId,EditorialWorkflowV5.ChapterState.L1_READY,EditorialWorkflowV5.ChapterState.L1_RUNNING);repo.transitionChapter(chapterId,EditorialWorkflowV5.ChapterState.L1_RUNNING,EditorialWorkflowV5.ChapterState.L1_CLOSED);AtomicInteger calls=new AtomicInteger();EditorialL2Runner runner=new EditorialL2Runner(repo,(settings,prompt,id)->{OpenAICompatibleClient.ChatResult response=new OpenAICompatibleClient.ChatResult();if(calls.getAndIncrement()==0){assertTrue(prompt.user.contains("RAW_SECRET"));assertFalse(prompt.user.contains("DRAFT_SECRET"));assertFalse(prompt.user.contains("REPORT_L1"));response.content="{\"chapterId\":\""+chapterId+"\",\"scenes\":[{\"id\":\"s1\",\"rawStart\":\"p1\",\"rawEnd\":\"p1\",\"pov\":\"A\",\"cast\":\"A\",\"event\":\"E\",\"risk\":\"R\",\"status\":\"CLOSED\"}]}";}else{assertTrue(prompt.user.contains("DRAFT_SECRET"));assertTrue(prompt.user.contains("REPORT_L1"));response.content="{\"schema\":\"editorial-v5-evidence-1\",\"run\":\"L2\",\"chapterId\":\""+chapterId+"\",\"output\":\"VI\",\"outputComplete\":true,\"globalChanges\":[],\"gates\":{\"coverage\":\"CLOSED\",\"fidelity\":\"CLOSED\",\"referenceVoice\":\"CLOSED\",\"continuityStructure\":\"CLOSED\",\"change\":\"CLOSED\"}}";}return response;});EditorialL2Runner.Result result=runner.run(chapterId,new AppSettings());assertEquals(2,calls.get());assertEquals("VI",result.output);assertEquals(EditorialWorkflowV5.ChapterState.L2_CLOSED,repo.getChapter(chapterId).state);assertFalse(repo.evidencePayload(result.runId,"L2_RAW_LEDGER").isEmpty());
        }finally{if(projectId>0)repo.deleteProject(projectId);repo.close();}
    }
    @Test public void segmentedL2RetryCallsOnlyFailedEditScene() throws Exception {EditorialRepository repo=new EditorialRepository(ApplicationProvider.getApplicationContext());long projectId=-1;try{EditorialRepository.Project project=new EditorialRepository.Project();project.seriesName="QA L2 Retry "+System.nanoTime();project.volumeName="V1";project.workflowHash=HashUtil.sha256("v5");projectId=repo.createProject(project);String raw=repeat('原',7000)+"\n◇◇◇\n"+repeat('終',7000),draft=repeat('a',7000)+"\n◇◇◇\n"+repeat('b',7000);long chapterId=repo.createChapter(projectId,"L2R","L2 retry",Arrays.asList(new EditorialRepository.AssetSnapshot(EditorialWorkflowV5.AssetRole.RAW,"m://r","r.txt",raw),new EditorialRepository.AssetSnapshot(EditorialWorkflowV5.AssetRole.DRAFT,"m://d","d.txt",draft),new EditorialRepository.AssetSnapshot(EditorialWorkflowV5.AssetRole.GLOSSARY,"m://g","g.txt","G"),new EditorialRepository.AssetSnapshot(EditorialWorkflowV5.AssetRole.PRONOUN,"m://p","p.txt","P")));long l1=repo.createRun(chapterId,"L1","fake","fake",HashUtil.sha256("p"),project.workflowHash,"{}");String report="{\"schema\":\"editorial-v5-evidence-1\",\"run\":\"L1\",\"chapterId\":\""+chapterId+"\",\"scenes\":[{\"id\":\"scene-001\",\"rawStart\":\"p000001\",\"rawEnd\":\"p000002\",\"coverage\":\"ALIGNED\",\"status\":\"CLOSED\"},{\"id\":\"scene-002\",\"rawStart\":\"p000003\",\"rawEnd\":\"p000003\",\"coverage\":\"ALIGNED\",\"status\":\"CLOSED\"}],\"issues\":[],\"gates\":{\"coverage\":\"CLOSED\",\"fidelity\":\"CLOSED\",\"referenceVoice\":\"CLOSED\",\"continuityStructure\":\"CLOSED\"}}";repo.saveEvidence(l1,"REPORT_L1_JSON",report);repo.transitionChapter(chapterId,EditorialWorkflowV5.ChapterState.L1_READY,EditorialWorkflowV5.ChapterState.L1_RUNNING);repo.transitionChapter(chapterId,EditorialWorkflowV5.ChapterState.L1_RUNNING,EditorialWorkflowV5.ChapterState.L1_CLOSED);AtomicInteger calls=new AtomicInteger();EditorialL2Runner runner=new EditorialL2Runner(repo,(settings,prompt,id)->{int call=calls.incrementAndGet();OpenAICompatibleClient.ChatResult r=new OpenAICompatibleClient.ChatResult();Matcher scene=Pattern.compile("(?:EXPECTED SCENE:|SCENE:) (scene-\\d+)").matcher(prompt.user);assertTrue(scene.find());String sid=scene.group(1);Matcher anchors=Pattern.compile(sid+" \\| (p\\d+) -> (p\\d+)|EXPECTED RAW ANCHORS: (p\\d+) -> (p\\d+)").matcher(prompt.user);assertTrue(anchors.find());String start=anchors.group(1)!=null?anchors.group(1):anchors.group(3),end=anchors.group(2)!=null?anchors.group(2):anchors.group(4);if(id.contains(":raw:"))r.content="{\"chapterId\":\""+chapterId+"\",\"scenes\":[{\"id\":\""+sid+"\",\"rawStart\":\""+start+"\",\"rawEnd\":\""+end+"\",\"pov\":\"A\",\"cast\":\"A\",\"event\":\"E\",\"risk\":\"R\",\"status\":\"CLOSED\"}]}";else if("scene-002".equals(sid)&&call==4)r.content="invalid";else r.content="{\"sceneId\":\""+sid+"\",\"rawStart\":\""+start+"\",\"rawEnd\":\""+end+"\",\"output\":\"VI-"+sid+"\",\"outputComplete\":true,\"changes\":[],\"gates\":{\"coverage\":\"CLOSED\",\"fidelity\":\"CLOSED\",\"referenceVoice\":\"CLOSED\",\"continuityStructure\":\"CLOSED\",\"change\":\"CLOSED\"}}";return r;});try{runner.run(chapterId,new AppSettings());fail();}catch(Exception expected){assertEquals(EditorialWorkflowV5.ChapterState.FAILED,repo.getChapter(chapterId).state);}EditorialL2Runner.Result result=runner.retry(chapterId,new AppSettings());assertEquals(5,calls.get());assertEquals("VI-scene-001VI-scene-002",result.output);assertEquals(EditorialWorkflowV5.ChapterState.L2_CLOSED,repo.getChapter(chapterId).state);}finally{if(projectId>0)repo.deleteProject(projectId);repo.close();}}
    @Test public void l3HidesReportUntilIndependentCheckpointCloses() throws Exception{EditorialRepository repo=new EditorialRepository(ApplicationProvider.getApplicationContext());long projectId=-1;try{EditorialRepository.Project project=new EditorialRepository.Project();project.seriesName="QA L3 "+System.nanoTime();project.volumeName="V1";project.workflowHash=HashUtil.sha256("v5");projectId=repo.createProject(project);long chapterId=repo.createChapter(projectId,"L3","L3",Arrays.asList(new EditorialRepository.AssetSnapshot(EditorialWorkflowV5.AssetRole.RAW,"m://r","r.txt","RAW_SECRET"),new EditorialRepository.AssetSnapshot(EditorialWorkflowV5.AssetRole.DRAFT,"m://d","d.txt","D"),new EditorialRepository.AssetSnapshot(EditorialWorkflowV5.AssetRole.GLOSSARY,"m://g","g.txt","G"),new EditorialRepository.AssetSnapshot(EditorialWorkflowV5.AssetRole.PRONOUN,"m://p","p.txt","P")));long l1=repo.createRun(chapterId,"L1","fake","fake",HashUtil.sha256("p"),project.workflowHash,"{}");String report="{\"schema\":\"editorial-v5-evidence-1\",\"run\":\"L1\",\"chapterId\":\""+chapterId+"\",\"scenes\":[{\"id\":\"s1\",\"rawStart\":\"p1\",\"rawEnd\":\"p1\",\"coverage\":\"ALIGNED\",\"status\":\"CLOSED\"}],\"issues\":[],\"gates\":{\"coverage\":\"CLOSED\",\"fidelity\":\"CLOSED\",\"referenceVoice\":\"CLOSED\",\"continuityStructure\":\"CLOSED\"}}";repo.saveEvidence(l1,"REPORT_L1_JSON",report);long l2=repo.createRun(chapterId,"L2","fake","fake",HashUtil.sha256("p2"),project.workflowHash,"{}");String viJson="{\"schema\":\"editorial-v5-evidence-1\",\"run\":\"L2\",\"chapterId\":\""+chapterId+"\",\"output\":\"VI_SECRET\",\"outputComplete\":true,\"globalChanges\":[],\"gates\":{\"coverage\":\"CLOSED\",\"fidelity\":\"CLOSED\",\"referenceVoice\":\"CLOSED\",\"continuityStructure\":\"CLOSED\",\"change\":\"CLOSED\"}}";repo.saveEvidence(l2,"VI_L2_JSON",viJson);repo.saveEvidence(l2,"VI_L2_TEXT","VI_SECRET");repo.transitionChapter(chapterId,EditorialWorkflowV5.ChapterState.L1_READY,EditorialWorkflowV5.ChapterState.L1_RUNNING);repo.transitionChapter(chapterId,EditorialWorkflowV5.ChapterState.L1_RUNNING,EditorialWorkflowV5.ChapterState.L1_CLOSED);repo.transitionChapter(chapterId,EditorialWorkflowV5.ChapterState.L1_CLOSED,EditorialWorkflowV5.ChapterState.L2_READY);repo.transitionChapter(chapterId,EditorialWorkflowV5.ChapterState.L2_READY,EditorialWorkflowV5.ChapterState.L2_RAW_MAPPING);repo.transitionChapter(chapterId,EditorialWorkflowV5.ChapterState.L2_RAW_MAPPING,EditorialWorkflowV5.ChapterState.L2_RUNNING);repo.transitionChapter(chapterId,EditorialWorkflowV5.ChapterState.L2_RUNNING,EditorialWorkflowV5.ChapterState.L2_CLOSED);AtomicInteger calls=new AtomicInteger();EditorialL3Runner runner=new EditorialL3Runner(repo,(settings,prompt,id)->{OpenAICompatibleClient.ChatResult r=new OpenAICompatibleClient.ChatResult();if(calls.getAndIncrement()==0){assertTrue(prompt.user.contains("RAW_SECRET"));assertTrue(prompt.user.contains("VI_SECRET"));assertFalse(prompt.user.contains("REPORT_L1"));r.content="{\"chapterId\":\""+chapterId+"\",\"scenes\":[{\"id\":\"s1\",\"rawStart\":\"p1\",\"rawEnd\":\"p1\",\"coverage\":\"ALIGNED\",\"fidelity\":\"CLOSED\",\"voice\":\"CLOSED\",\"status\":\"CLOSED\"}],\"issues\":[],\"crossSceneVoiceAudit\":\"CLOSED\",\"status\":\"CLOSED\"}";}else{assertTrue(prompt.user.contains("REPORT_L1"));r.content="{\"schema\":\"editorial-v5-evidence-1\",\"run\":\"L3\",\"chapterId\":\""+chapterId+"\",\"output\":\"FINAL\",\"outputComplete\":true,\"changeSet\":[],\"crossSceneVoiceAudit\":\"CLOSED\",\"finalReadThrough\":\"CLOSED\",\"gates\":{\"coverage\":\"CLOSED\",\"fidelity\":\"CLOSED\",\"referenceVoice\":\"CLOSED\",\"continuityStructure\":\"CLOSED\",\"change\":\"CLOSED\"}}";}return r;});EditorialL3Runner.Result result=runner.run(chapterId,new AppSettings());assertEquals(2,calls.get());assertEquals("FINAL",result.output);assertEquals(EditorialWorkflowV5.ChapterState.RELEASE_READY,repo.getChapter(chapterId).state);assertFalse(repo.evidencePayload(result.runId,"L3_INDEPENDENT_LEDGER").isEmpty());}finally{if(projectId>0)repo.deleteProject(projectId);repo.close();}}
    @Test public void segmentedL3RetryCallsOnlyFailedFinalScene() throws Exception{EditorialRepository repo=new EditorialRepository(ApplicationProvider.getApplicationContext());long projectId=-1;try{EditorialRepository.Project project=new EditorialRepository.Project();project.seriesName="QA L3 Retry "+System.nanoTime();project.volumeName="V1";project.workflowHash=HashUtil.sha256("v5");projectId=repo.createProject(project);String raw=repeat('原',7000)+"\n◇◇◇\n"+repeat('終',7000);long chapterId=repo.createChapter(projectId,"L3R","L3 retry",Arrays.asList(new EditorialRepository.AssetSnapshot(EditorialWorkflowV5.AssetRole.RAW,"m://r","r.txt",raw),new EditorialRepository.AssetSnapshot(EditorialWorkflowV5.AssetRole.DRAFT,"m://d","d.txt","D"),new EditorialRepository.AssetSnapshot(EditorialWorkflowV5.AssetRole.GLOSSARY,"m://g","g.txt","G"),new EditorialRepository.AssetSnapshot(EditorialWorkflowV5.AssetRole.PRONOUN,"m://p","p.txt","P")));long l1=repo.createRun(chapterId,"L1","fake","fake",HashUtil.sha256("p"),project.workflowHash,"{}");String report="{\"schema\":\"editorial-v5-evidence-1\",\"run\":\"L1\",\"chapterId\":\""+chapterId+"\",\"scenes\":[{\"id\":\"scene-001\",\"rawStart\":\"p000001\",\"rawEnd\":\"p000002\",\"coverage\":\"ALIGNED\",\"status\":\"CLOSED\"},{\"id\":\"scene-002\",\"rawStart\":\"p000003\",\"rawEnd\":\"p000003\",\"coverage\":\"ALIGNED\",\"status\":\"CLOSED\"}],\"issues\":[],\"gates\":{\"coverage\":\"CLOSED\",\"fidelity\":\"CLOSED\",\"referenceVoice\":\"CLOSED\",\"continuityStructure\":\"CLOSED\"}}";repo.saveEvidence(l1,"REPORT_L1_JSON",report);long l2=repo.createRun(chapterId,"L2","fake","fake",HashUtil.sha256("p2"),project.workflowHash,"{}");String gates="\"gates\":{\"coverage\":\"CLOSED\",\"fidelity\":\"CLOSED\",\"referenceVoice\":\"CLOSED\",\"continuityStructure\":\"CLOSED\",\"change\":\"CLOSED\"}";repo.saveEvidence(l2,"L2_EDIT_SCENE_scene-001","{\"sceneId\":\"scene-001\",\"rawStart\":\"p000001\",\"rawEnd\":\"p000002\",\"output\":\"VI1\",\"outputComplete\":true,\"changes\":[],"+gates+"}");repo.saveEvidence(l2,"L2_EDIT_SCENE_scene-002","{\"sceneId\":\"scene-002\",\"rawStart\":\"p000003\",\"rawEnd\":\"p000003\",\"output\":\"VI2\",\"outputComplete\":true,\"changes\":[],"+gates+"}");String viJson="{\"schema\":\"editorial-v5-evidence-1\",\"run\":\"L2\",\"chapterId\":\""+chapterId+"\",\"output\":\"VI1VI2\",\"outputComplete\":true,\"globalChanges\":[],"+gates+"}";repo.saveEvidence(l2,"VI_L2_JSON",viJson);repo.saveEvidence(l2,"VI_L2_TEXT","VI1VI2");repo.transitionChapter(chapterId,EditorialWorkflowV5.ChapterState.L1_READY,EditorialWorkflowV5.ChapterState.L1_RUNNING);repo.transitionChapter(chapterId,EditorialWorkflowV5.ChapterState.L1_RUNNING,EditorialWorkflowV5.ChapterState.L1_CLOSED);repo.transitionChapter(chapterId,EditorialWorkflowV5.ChapterState.L1_CLOSED,EditorialWorkflowV5.ChapterState.L2_READY);repo.transitionChapter(chapterId,EditorialWorkflowV5.ChapterState.L2_READY,EditorialWorkflowV5.ChapterState.L2_RAW_MAPPING);repo.transitionChapter(chapterId,EditorialWorkflowV5.ChapterState.L2_RAW_MAPPING,EditorialWorkflowV5.ChapterState.L2_RUNNING);repo.transitionChapter(chapterId,EditorialWorkflowV5.ChapterState.L2_RUNNING,EditorialWorkflowV5.ChapterState.L2_CLOSED);AtomicInteger calls=new AtomicInteger();EditorialL3Runner runner=new EditorialL3Runner(repo,(settings,prompt,id)->{int call=calls.incrementAndGet();OpenAICompatibleClient.ChatResult r=new OpenAICompatibleClient.ChatResult();if(id.endsWith(":voice-audit")){assertFalse(prompt.user.contains("REPORT_L1"));r.content="{\"chapterId\":\""+chapterId+"\",\"findings\":[],\"crossSceneVoiceAudit\":\"CLOSED\",\"status\":\"CLOSED\"}";return r;}Matcher scene=Pattern.compile("(?:EXPECTED SCENE:|SCENE:) (scene-\\d+)").matcher(prompt.user);assertTrue(scene.find());String sid=scene.group(1);Matcher anchors=Pattern.compile(sid+" \\| (p\\d+) -> (p\\d+)|EXPECTED RAW ANCHORS: (p\\d+) -> (p\\d+)").matcher(prompt.user);assertTrue(anchors.find());String start=anchors.group(1)!=null?anchors.group(1):anchors.group(3),end=anchors.group(2)!=null?anchors.group(2):anchors.group(4);if(id.contains(":independent:")){assertFalse(prompt.user.contains("REPORT_L1"));r.content="{\"chapterId\":\""+chapterId+"\",\"scenes\":[{\"id\":\""+sid+"\",\"rawStart\":\""+start+"\",\"rawEnd\":\""+end+"\",\"coverage\":\"ALIGNED\",\"fidelity\":\"CLOSED\",\"voice\":\"CLOSED\",\"status\":\"CLOSED\"}],\"issues\":[],\"crossSceneVoiceAudit\":\"CLOSED\",\"status\":\"CLOSED\"}";}else if("scene-002".equals(sid)&&call==5)r.content="invalid";else{assertTrue(prompt.user.contains("REPORT_L1"));r.content="{\"sceneId\":\""+sid+"\",\"rawStart\":\""+start+"\",\"rawEnd\":\""+end+"\",\"output\":\"F-"+sid+"\",\"outputComplete\":true,\"changeSet\":[],\"finalReadThrough\":\"CLOSED\","+gates+"}";}return r;});try{runner.run(chapterId,new AppSettings());fail();}catch(Exception expected){assertEquals(EditorialWorkflowV5.ChapterState.FAILED,repo.getChapter(chapterId).state);}EditorialL3Runner.Result result=runner.retry(chapterId,new AppSettings());assertEquals(6,calls.get());assertEquals("F-scene-001F-scene-002",result.output);assertEquals(EditorialWorkflowV5.ChapterState.RELEASE_READY,repo.getChapter(chapterId).state);}finally{if(projectId>0)repo.deleteProject(projectId);repo.close();}}
    private static String repeat(char value,int count){StringBuilder out=new StringBuilder(count);for(int i=0;i<count;i++)out.append(value);return out.toString();}
}
